  1462	\paragraph{Formalization support for marginal reduction and rank zero.}
  1463	The following auxiliary results are not named statements of the paper. They
  1464	isolate the marginal-state and finite-rank facts used by the formal proofs of
  1465	Lemma~\ref{lem:locality-preserving-projectivization} and
  1466	Lemma~\ref{lem:ortho-explicit-constant}.
  1467	
  1468	\begin{definition}[Formalization support for marginal reduction]
  1469		\label{def:left-marginal-state}
  1470		\lean{MIPStarRE.LDT.MakingMeasurementsProjective.leftMarginalState}
  1471		\leanok
  1472		Let $\rho$ be the density operator of a state on
  1473		$\hilb_{\mathsf A}\ot\hilb_{\mathsf B}$, where $\hilb_{\mathsf B}$ is nonzero
  1474		and both spaces are finite dimensional. Relative to an orthonormal basis $\{e_b\}$ of
  1475		$\hilb_{\mathsf B}$, define its normalized left marginal $\rho_{\mathsf A}$ by
  1476		\[
  1477			\bra{i}\rho_{\mathsf A}\ket{j}
  1478			= \frac{1}{\dim \hilb_{\mathsf B}}\sum_b
  1479			\bra{i,e_b}\rho\ket{j,e_b}.
  1480		\]
  1481		The dimension factor reflects the normalized-trace convention used for
  1482		finite matrix states in Lean.
  1483	\end{definition}
  1484	
  1485	\begin{lemma}[Formalization support for marginal evaluation]
  1486		\label{lem:left-marginal-state-evaluation}
  1487		\lean{MIPStarRE.LDT.MakingMeasurementsProjective.leftMarginal_ev_eq}
  1488		\leanok
  1489		\uses{def:left-marginal-state}
  1490		For every operator $X$ on $\hilb_{\mathsf A}$,
  1491		\[
  1492			\operatorname{Tr}_{\mathrm{norm}}\!\bigl(\rho(X\ot\Id_{\mathsf B})\bigr)
  1493			= \operatorname{Tr}_{\mathrm{norm}}\!\bigl(\rho_{\mathsf A}X\bigr).
  1494		\]
  1495	\end{lemma}
  1496	\begin{proof}
  1497		\leanok
  1498		Expand both normalized traces in the chosen product basis and sum the
  1499		diagonal $\mathsf B$-blocks.
  1500	\end{proof}
  1501	
  1502	\begin{lemma}[Formalization support for marginal normalization]
  1503		\label{lem:left-marginal-state-normalization}
  1504		\lean{MIPStarRE.LDT.MakingMeasurementsProjective.leftMarginalState_isNormalized}
  1505		\leanok
  1506		\uses{def:left-marginal-state, lem:left-marginal-state-evaluation}
  1507		If $\rho$ is normalized, then its normalized left marginal
  1508		$\rho_{\mathsf A}$ is normalized as well.
  1509	\end{lemma}
  1510	\begin{proof}
  1511		\leanok
  1512		Take $X=\Id_{\mathsf A}$ in the marginal-evaluation identity and use the
  1513		normalization of $\rho$.
  1514	\end{proof}
  1515	
  1516	\begin{lemma}[Formalization support for rank-zero matrices]
  1517		\label{lem:matrix-rank-zero}
  1518		\lean{MIPStarRE.LDT.MakingMeasurementsProjective.matrix_eq_zero_of_rank_eq_zero}
  1519		\leanok
  1520		If a complex matrix between finite coordinate spaces has rank zero, then it
  1521		is the zero matrix.
  1522	\end{lemma}
  1523	\begin{proof}
  1524		\leanok
  1525		The range of the associated linear map has dimension zero and is therefore
  1526		the zero subspace. Applying the map to each coordinate vector shows that every
  1527		matrix entry vanishes.
  1528	\end{proof}
